#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    const char* results = "Test data";
    char temp_file[] = "/tmp/temp_XXXXXX";

    int fd = mkstemp(temp_file);
    if (fd == -1) {
        printf("Failed to create temporary file\n");
        return EXIT_FAILURE;
    }

    FILE* file = fdopen(fd, "w");
    if (!file) {
        close(fd);
        unlink(temp_file);
        printf("Failed to open temporary file\n");
        return EXIT_FAILURE;
    }

    fprintf(file, "%s", results);
    fclose(file);

    printf("Temporary file created: %s\n", temp_file);

    return EXIT_SUCCESS;
}
